<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/reviews';import * as reports from '../api/reports';import {download} from '../api/client';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import GroupTable from '../components/GroupTable.vue';const props=defineProps<{data:Workspace;canWrite:boolean;isAdmin:boolean;refresh:()=>Promise<void>}>();const id=ref(''),note=ref(''),decision=ref('accepted'),completed=computed(()=>props.data.runs.filter(r=>r.status==='completed')),run=computed(()=>completed.value.find(r=>r.id===id.value)||completed.value[0]),reviews=computed(()=>props.data.reviews.filter(v=>v.run_id===run.value?.id).sort((a,b)=>b.version-a.version));const{busy,error,notice,act}=useAction();</script><template><Heading index="06 / FOOTPRINT REVIEW" title="包络是证据，覆盖仍需解释。" detail="每次复核新增不可变版本；负责人批准最新接受版本，CSV保存真实边界顶点、框角、米制面积与来源计数。"/><label class="selector">复核运行<select aria-label="复核运行" v-model="id"><option value="">最近完成的包络比较</option><option v-for="r in completed" :key="r.id" :value="r.id">{{data.studies.find(s=>s.id===r.study_id)?.name}} · {{r.id.slice(0,12)}}</option></select></label><Empty v-if="!run">先完成包络比较，再复核重复处理、退化几何和凹口解释。</Empty><template v-else><GroupTable :groups="run.result.groups"/><section v-if="canWrite" class="form-section"><form @submit.prevent="act(async()=>{await create({run_id:run!.id,note,decision});await refresh()},'新的足迹复核版本已保存')"><label>复核依据与边界解释<textarea aria-label="复核依据与边界解释" rows="3" required minlength="10" v-model="note"/></label><label>足迹复核结论<select aria-label="足迹复核结论" v-model="decision"><option value="accepted">接受并提请归档</option><option value="needs_changes">待补充依据</option></select></label><button class="primary" :disabled="busy">提交足迹复核版本</button></form><Notice :error="error" :notice="notice"/></section><div class="section-rule"><h2>复核版本与批准归档</h2><span>旧CSV保持原复核ID</span></div><article v-for="(v,i) in reviews" :key="v.id" class="review-row"><div><p class="eyebrow">VERSION {{v.version}} / {{v.decision==='accepted'?'接受':'待补充'}} / {{v.author}}</p><p>{{v.note}}</p></div><div><button v-if="isAdmin&&i===0&&v.decision==='accepted'&&!data.reports.some(r=>r.review_id===v.id)" @click="act(async()=>{await reports.create({run_id:run!.id,title:'岚图采集足迹·包络复核v'+v.version});await refresh()},'最新接受版本已批准归档')">批准最新版本归档</button><button v-for="r in data.reports.filter(r=>r.review_id===v.id)" :key="r.id" @click="act(()=>download(r.id),'CSV已下载')">下载CSV · v{{v.version}}</button></div></article></template><details><summary>操作与拒绝审计</summary><div class="table-scroll"><table><thead><tr><th>操作人</th><th>请求</th><th>HTTP</th></tr></thead><tbody><tr v-for="a in data.audit.slice(0,20)" :key="a.id"><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.status}}</td></tr></tbody></table></div></details></template>